  );
  readonly option = computed<SdTableOption<MatrixRow>>(() => {
    const rows = this.rows();
    return {
      type: 'local',
      items: () => rows,
      rowKey: 'id',
      columns: [
        { field: 'name', title: 'Chức năng', type: 'string', width: '290px' },
