        { field: 'other', title: 'Other / Quyền khác', type: 'string', width: '320px' },
      ],
      paginate: { hidden: true, pageSize: Math.max(rows.length, 1) },
      filter: { disabled: true },
      sort: { enable: false },
      config: { visible: false },
    };
  });
}

