  readonly baseline = signal('');
  readonly viewed = computed(() => this.mode() === 'detail');
  readonly title = computed(() => (this.mode() === 'create' ? 'Tạo vai trò' : this.viewed() ? 'Chi tiết vai trò' : 'Cập nhật vai trò'));
  readonly value = computed<RoleRecord>(() => ({ ...this.seed(), ...this.fields(), permissions: this.selected() }));
  readonly dirty = computed(() => !this.viewed() && roleFingerprint(this.value()) !== this.baseline());
  constructor() {
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.syncFields());
    // Core controls register first, then silently apply their initial model values.
    // Read once after that render so pristine fields are not mistaken for edits.
    afterNextRender(() => this.syncFields());
  }
  private syncFields(): void {
    const fields = this.form.getRawValue() as Partial<RoleRecord>;
    if ('description' in fields) fields.description ??= '';
    this.fields.set(fields);
  }
  ngOnInit(): void {
    this.selected.set([...this.seed().permissions]);
    this.baseline.set(roleFingerprint(this.seed()));
    const registration = this.unsaved.register({
      id: 'role-draft',
      scope: this,
      isDirty: this.dirty,
      save: () => this.save(false),
      discard: () => {
        this.baseline.set(roleFingerprint(this.value()));
        return true;
      },
    });
    this.destroy.onDestroy(() => registration.destroy());
    if ((this.location.getState() as { roleSaved?: boolean })?.roleSaved) this.savedMessage.set('Đã lưu vai trò.');
  }
  canLeave(): Promise<boolean> {
    return this.saving() ? Promise.resolve(false) : this.unsaved.confirmLeave({ scope: this, reason: 'navigation' });
  }
  back(): void {
    if (!this.saving()) void this.router.navigateByUrl(roleBaseUrl(this.layout()));
  }
  edit(): void {
    void this.router.navigateByUrl(roleBaseUrl(this.layout()) + '/' + encodeURIComponent(this.seed().id) + '/update');
  }
  async save(navigate = true): Promise<boolean> {
    if (this.saving() || this.viewed()) return false;
    this.form.markAllAsTouched();
    this.form.updateValueAndValidity();
    if (this.form.invalid) {
      this.error.set('Vui lòng kiểm tra các trường bắt buộc.');
      return false;
    }
    this.error.set('');
    this.saving.set(true);
    try {
      const saved = await this.store.save(this.layout(), this.value());
      if (this.destroy.destroyed) return false;
      this.baseline.set(roleFingerprint(this.value()));
      this.form.markAsPristine();
      this.saving.set(false);
      if (navigate)
        await this.router.navigateByUrl(roleBaseUrl(this.layout()) + '/' + encodeURIComponent(saved.id) + '/detail', {
          replaceUrl: this.mode() === 'create',
          state: { roleSaved: true },
        });
      return true;
    } catch (error) {
      if (!this.destroy.destroyed) this.error.set(error instanceof Error ? error.message : 'Không thể lưu vai trò. Vui lòng thử lại.');
      return false;
    } finally {
      if (!this.destroy.destroyed) this.saving.set(false);
    }
  }
}

import { ChangeDetectionStrategy, Component, DestroyRef, inject, signal, viewChild } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { SdDataState } from '@sdcorejs/angular/components/data-state';
import { SdTabComponent } from '@sdcorejs/angular/components/tab-router';
import { RoleSessionStore } from '../data/role-session.store';
import { emptyRole, RoleLayout, RoleMode, RoleRecord, roleBaseUrl } from '../data/role.model';
import { RoleRecordEditorComponent } from './role-record-editor.component';
@Component({
  selector: 'app-role-record-page',
  providers: [RoleSessionStore],
  imports: [SdDataState, RoleRecordEditorComponent],
  template: `@if (loading()) {
      <sd-data-state state="loading" title="Đang mở vai trò…" />
    } @else if (error()) {
      <sd-data-state state="error" title="Không thể mở vai trò" [message]="error()" actionLabel="Quay lại danh sách" (sdAction)="back()" />
    } @else if (record(); as seed) {
      @for (key of [mode + ':' + seed.id]; track key) {
        <app-role-record-editor [seed]="seed" [layout]="layout" [mode]="mode" />
      }
    }`,
  styles: [
    `
      :host {
        display: block;
        height: 100%;
        min-width: 0;
      }
    `,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class RoleRecordPageComponent {
  readonly route = inject(ActivatedRoute);
  readonly router = inject(Router);
  readonly store = inject(RoleSessionStore);
  readonly destroy = inject(DestroyRef);
  readonly layout = this.route.snapshot.data['roleLayout'] as RoleLayout;
  readonly mode = this.route.snapshot.data['roleMode'] as RoleMode;
  readonly loading = signal(true);
  readonly error = signal('');
  readonly record = signal<RoleRecord | null>(null);
  readonly editor = viewChild(RoleRecordEditorComponent);
  private request = 0;
  constructor() {
    this.route.paramMap.pipe(takeUntilDestroyed()).subscribe(params => void this.load(params.get('id')));
  }
  async load(id: string | null): Promise<void> {
    const request = ++this.request;
    this.loading.set(true);
    this.error.set('');
    this.record.set(null);
    try {
      const rows = await this.store.list(this.layout);
      if (request !== this.request || this.destroy.destroyed) return;
      const record = this.mode === 'create' ? emptyRole() : rows.find(row => row.id === id);
      if (!record) throw new Error('Không tìm thấy vai trò. Hãy chọn lại từ danh sách.');
      this.record.set(record);
    } catch (error) {
      if (request === this.request && !this.destroy.destroyed)
        this.error.set(error instanceof Error ? error.message : 'Không thể tải dữ liệu.');
    } finally {
      if (request === this.request && !this.destroy.destroyed) this.loading.set(false);
    }
  }
  canLeave(): Promise<boolean> {
    return this.editor()?.canLeave() ?? Promise.resolve(true);
  }
  back(): void {
    void this.router.navigateByUrl(roleBaseUrl(this.layout));
  }
}
SdTabComponent({
  component: RoleRecordPageComponent,
  name: args => (args.data?.['roleMode'] === 'create' ? 'Tạo vai trò' : 'Hồ sơ vai trò'),
  icon: 'shield',
})(RoleRecordPageComponent);

