// why: constrain nested reference composition without overriding Core component internals.
.reference-workspace {
  min-width: 0;
  max-width: 1600px;
  margin-inline: auto;
}
// why: responsive master/detail proportions are specific to these page examples.
.reference-master-detail {
  display: grid;
  grid-template-columns: minmax(0, 3fr) minmax(300px, 2fr);
  gap: 16px;
}
// why: wide table scroll must stay inside the example at mobile widths.
.reference-table-region {
  min-width: 0;
  overflow-x: auto;
}
// why: match the actual viewport for embedded previews and Storybook canvas.
.reference-preview {
  min-width: 0;
  min-height: 540px;
  border: 1px solid var(--sd-border);
  border-radius: 8px;
  background: var(--sd-surface);
}
// why: token-based page background coordinates existing demos and new reference examples.
.demo-page-body {
  padding: 24px;
  background: var(--sd-surface);
}
// why: prose and generated code must wrap without expanding the app viewport.
.reference-source {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  max-height: 640px;
  overflow: auto;
}
// why: two coordinated responsive regions become a single reading order on narrow screens.
